{"cards": [{"node_code": "N_c1296420bb692be5", "definition": "水路运输领域（含船舶、港口、航道设施）的火灾预防、灭火技术、消防设备配置及消防安全管理制度，旨在控制火源、抑制火势蔓延并保障人员与财产安全。", "boundary": "本节点聚焦于“防火”这一特定风险源。边界在于区分“防火”与“防污染”（油污处理归入水域防污）、“防汛”（自然灾害归入防汛防台风）。若涉及船舶结构耐火设计，归入船舶工程；若涉及港口建筑消防设计，归入港口工程。本节点侧重运营过程中的消防管理、操作规程及应急灭火。", "includes": ["船舶与港口设施的火灾风险评估与预防措施", "消防设备（灭火器、喷淋系统）的配置、维护及使用规范", "火灾事故应急预案、灭火战术及消防安全检查制度"], "excludes": ["船舶或港口建筑结构的耐火材料选型与结构设计", "水域油污泄漏的清理与防污染技术", "防汛、防台风等自然灾害的防御工程"], "sibling_distinctions": [{"other_code": "N_7feed2e3d90d2e39", "rule": "本节点针对“火灾”风险，兄弟节点针对“水污染”风险。"}, {"other_code": "N_6dba286c8e793f7a", "rule": "本节点针对“人为或设备故障引发的火灾”，兄弟节点针对“气象水文灾害”。"}], "cross_boundary_rule": "若内容涉及“消防设备的设计与制造原理”，主挂载相关工程节点；若涉及“消防管理制度、操作规程、应急演练”，主挂载本节点。"}, {"node_code": "N_a576b1c5049d831c", "definition": "港口生产作业过程中的安全生产管理，涵盖码头、堆场、装卸机械等作业环境的安全规程、危险源辨识、职业健康防护及事故预防体系。", "boundary": "本节点聚焦于“港口”这一特定场所的“安全生产”。边界在于区分“港口安全生产”与“船舶航行安全”（归入客运/货运安全或航海技术）、“航道通航安全”（归入航道管理）。若涉及港口设施的结构安全设计，归入港口工程。本节点侧重港口陆域及水域作业面的安全管理与风险控制。", "includes": ["港口装卸、搬运、堆存作业的安全操作规程", "港口危险货物（危化品）作业的安全管理与监控", "港口作业人员劳动保护、职业健康及现场安全监督"], "excludes": ["船舶在港期间的航行操纵安全（归入航海技术或船舶安全）", "港口码头、仓库等基础设施的结构强度与工程设计", "港口企业的经济效益分析与成本核算"], "sibling_distinctions": [{"other_code": "N_84031830dd084073", "rule": "本节点侧重“港口陆域及作业区”的安全，兄弟节点侧重“船舶客舱及旅客”的安全。"}, {"other_code": "N_1af24b76235efd16", "rule": "本节点侧重“港口作业环境”的安全，兄弟节点侧重“货物本身及商务流程”的安全。"}], "cross_boundary_rule": "若内容涉及“港口安全设施（如护栏、警示系统）的设计”，主挂载港口工程；若涉及“港口安全管理制度、作业规范、事故预防”，主挂载本节点。"}, {"node_code": "N_4792d8b2158e7cfb", "definition": "水路运输事故（含碰撞、搁浅、火灾、污染等）的调查程序、原因分析方法、责任认定、统计报告及后续整改措施，旨在通过事故复盘提升安全水平。", "boundary": "本节点聚焦于“事故后”的分析与处理。边界在于区分“事故分析”与“事故预防”（预防归入各专项安全技术如防火、防汛）、“事故救援”（救援归入救助打捞或应急技术）。若涉及事故造成的环境污染处理，归入水域防污。本节点侧重事故调查方法论、案例分析及管理改进。", "includes": ["水路运输事故调查程序、证据收集与现场勘查技术", "事故原因分析模型、责任认定标准及法律适用", "事故统计、报告制度及基于事故教训的安全管理改进措施"], "excludes": ["事故现场的紧急救援、打捞及清污作业技术", "事故预防的具体工程技术措施（如防火、防碰撞设计）", "事故相关的法律诉讼程序及赔偿计算（归入法律或经济类）"], "sibling_distinctions": [{"other_code": "N_c1296420bb692be5", "rule": "本节点侧重“事故后的调查与分析”，兄弟节点侧重“火灾的预防与灭火”。"}, {"other_code": "N_7feed2e3d90d2e39", "rule": "本节点侧重“事故整体分析”，兄弟节点侧重“污染源的识别与治理”。"}], "cross_boundary_rule": "若内容涉及“事故救援技术”，主挂载救助打捞或应急技术节点；若涉及“事故调查、原因分析、责任认定”，主挂载本节点。"}]}
